const reportDate = $('Set Report Date').first().json.reportDate;
const summary = $('Get Summary').first().json;
const topProducts = $('Get Top Products').all().map(item => item.json).filter(p => p.Sku);
const alerts = $('Get Alerts').all().map(item => item.json).filter(a => a.AlertType);

const money = value =>
  new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(Number(value ?? 0));

const escapeHtml = value =>
  String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const formatDate = isoDate =>
  new Date(`${isoDate}T12:00:00Z`).toLocaleDateString('en-US', {
    weekday: 'long', month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC'
  });

const comparisonDate = new Date(`${reportDate}T12:00:00Z`);
comparisonDate.setUTCDate(comparisonDate.getUTCDate() - 7);
const comparisonIso = comparisonDate.toISOString().slice(0, 10);

const change = summary.RevenueChangePercent;
const hasChange = change !== null && change !== undefined;
const changeText = hasChange ? `${change > 0 ? '+' : ''}${Number(change).toFixed(1)}%` : 'n/a';
const changeColor = !hasChange ? '#667085' : change < 0 ? '#c0352b' : '#1f8a4c';

const cell = 'padding:10px 12px;border-bottom:1px solid #e4e7ec;';

const kpi = (label, value, color = '#1d2433') => `
  <td style="padding:12px 16px;border:1px solid #e4e7ec;background:#ffffff;">
    <div style="font-size:12px;color:#667085;">${label}</div>
    <div style="font-size:20px;font-weight:600;color:${color};">${value}</div>
  </td>`;

const productRows = topProducts.length > 0
  ? topProducts.map(p => `
      <tr>
        <td style="${cell}">${escapeHtml(p.Name)}</td>
        <td style="${cell}text-align:right;">${p.UnitsSold}</td>
        <td style="${cell}text-align:right;">${money(p.Revenue)}</td>
      </tr>`).join('')
  : `<tr><td colspan="3" style="${cell}">No sales on this day.</td></tr>`;

const alertItems = alerts
  .map(a => `<li style="margin-bottom:6px;">${a.AlertType === 'RevenueDrop' ? '📉' : '📦'} ${escapeHtml(a.Detail)}</li>`)
  .join('');

const alertsSection = alerts.length > 0 ? `
  <div style="margin-top:24px;padding:12px 16px;background:#fdecea;border-radius:8px;color:#c0352b;">
    <strong>${alerts.length} item(s) need attention</strong>
    <ul style="margin:8px 0 0;padding-left:20px;">${alertItems}</ul>
  </div>` : '';

const html = `
<div style="font-family:Segoe UI,Roboto,Arial,sans-serif;max-width:640px;margin:0 auto;color:#1d2433;">
  <h2 style="margin:0 0 4px;">Daily sales report</h2>
  <div style="color:#667085;margin-bottom:20px;">${formatDate(reportDate)}</div>

  <table style="border-collapse:collapse;width:100%;">
    <tr>
      ${kpi('Revenue', money(summary.Revenue))}
      ${kpi('Orders', summary.OrdersCount)}
      ${kpi('Average ticket', money(summary.AverageTicket))}
    </tr>
    <tr>
      ${kpi('Online', money(summary.OnlineRevenue))}
      ${kpi('Store', money(summary.StoreRevenue))}
      ${kpi(`vs ${formatDate(comparisonIso)}`, changeText, changeColor)}
    </tr>
  </table>

  <div style="font-size:13px;color:#667085;margin-top:8px;">
    Cancelled orders: ${summary.CancelledOrders}. Same weekday last week: ${money(summary.ComparisonRevenue)} from ${summary.ComparisonOrdersCount} orders.
  </div>

  ${alertsSection}

  <h3 style="margin:24px 0 8px;">Top products</h3>
  <table style="border-collapse:collapse;width:100%;">
    <tr style="text-align:left;color:#667085;font-size:12px;">
      <th style="${cell}">Product</th>
      <th style="${cell}text-align:right;">Units</th>
      <th style="${cell}text-align:right;">Revenue</th>
    </tr>
    ${productRows}
  </table>
</div>`;

const alertsHtml = `
<div style="font-family:Segoe UI,Roboto,Arial,sans-serif;max-width:640px;margin:0 auto;color:#1d2433;">
  <h2 style="margin:0 0 4px;color:#c0352b;">Sales alert</h2>
  <div style="color:#667085;margin-bottom:16px;">${formatDate(reportDate)}</div>
  <ul style="padding-left:20px;">${alertItems}</ul>
</div>`;

return [{
  json: {
    reportDate,
    subject: `Daily sales report: ${reportDate} | ${money(summary.Revenue)} (${changeText})`,
    html,
    hasAlerts: alerts.length > 0,
    alertSubject: `Sales alert: ${alerts.length} item(s) need attention on ${reportDate}`,
    alertsHtml
  }
}];
